arguments.file_text:
@page "/shipments"
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject ShipmentTracker.Client.Services.IShipmentService ShipmentService

<PageTitle>Shipments Dashboard</PageTitle>

<h1>Shipments Dashboard</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <label class="form-label">Filter by Status</label>
        <select class="form-select" @bind="selectedStatus" @bind:after="LoadShipments">
            <option value="">All</option>
            @foreach (var status in Enum.GetValues<ShipmentTracker.Client.Models.ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-4 d-flex align-items-end">
        <button class="btn btn-primary" @onclick="ShowCreateForm">+ New Shipment</button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-header">Create New Shipment</div>
        <div class="card-body">
            <div class="row g-3">
                <div class="col-md-4">
                    <label class="form-label">Origin</label>
                    <input class="form-control" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Destination</label>
                    <input class="form-control" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Customer Email</label>
                    <input class="form-control" type="email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-8">
                    <label class="form-label">Description</label>
                    <input class="form-control" @bind="newShipment.Description" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Estimated Delivery</label>
                    <input class="form-control" type="date" @bind="newShipment.EstimatedDelivery" />
                </div>
            </div>
            <div class="mt-3">
                <button class="btn btn-success" @onclick="CreateShipment" disabled="@isCreating">
                    @(isCreating ? "Creating..." : "Create")
                </button>
                <button class="btn btn-secondary ms-2" @onclick="() => showCreateForm = false">Cancel</button>
            </div>
        </div>
    </div>
}

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Customer</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in shipments)
                {
                    <tr>
                        <td><code>@shipment.TrackingNumber</code></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                        <td>@shipment.CustomerEmail</td>
                        <td>
                            <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                    value="@shipment.Status"
                                    @onchange="e => UpdateStatus(shipment, e)">
                                @foreach (var status in Enum.GetValues<ShipmentTracker.Client.Models.ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private List<ShipmentTracker.Client.Models.Shipment>? shipments;
    private string selectedStatus = "";
    private bool showCreateForm;
    private bool isCreating;
    private ShipmentTracker.Client.Models.Shipment newShipment = new() { EstimatedDelivery = DateTime.Today.AddDays(5) };

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        ShipmentTracker.Client.Models.ShipmentStatus? filter = null;
        if (Enum.TryParse<ShipmentTracker.Client.Models.ShipmentStatus>(selectedStatus, out var parsed))
        {
            filter = parsed;
        }
        shipments = await ShipmentService.GetShipmentsByStatusAsync(filter);
    }

    private void ShowCreateForm()
    {
        newShipment = new() { EstimatedDelivery = DateTime.Today.AddDays(5) };
        showCreateForm = true;
    }

    private async Task CreateShipment()
    {
        isCreating = true;
        await ShipmentService.CreateShipmentAsync(newShipment);
        showCreateForm = false;
        isCreating = false;
        await LoadShipments();
    }

    private async Task UpdateStatus(ShipmentTracker.Client.Models.Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentTracker.Client.Models.ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentTracker.Client.Models.ShipmentStatus status) => status switch
    {
        ShipmentTracker.Client.Models.ShipmentStatus.Pending => "bg-secondary",
        ShipmentTracker.Client.Models.ShipmentStatus.PickedUp => "bg-info",
        ShipmentTracker.Client.Models.ShipmentStatus.InTransit => "bg-primary",
        ShipmentTracker.Client.Models.ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentTracker.Client.Models.ShipmentStatus.Delivered => "bg-success",
        ShipmentTracker.Client.Models.ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@inject ShipmentTracker.Client.Services.IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input class="form-control" placeholder="Enter tracking number (e.g., TRK-001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isSearching">
                @(isSearching ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (searched && shipment == null)
{
    <div class="alert alert-warning">
        <strong>Not found.</strong> No shipment found with tracking number "<strong>@searchedNumber</strong>". Please check and try again.
    </div>
}

@if (shipment != null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Shipment <code>@shipment.TrackingNumber</code></h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@GetStatusDisplay(shipment.Status)</span></dd>

                        <dt>Origin</dt>
                        <dd>@shipment.Origin</dd>

                        <dt>Destination</dt>
                        <dd>@shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Description</dt>
                        <dd>@(string.IsNullOrEmpty(shipment.Description) ? "—" : shipment.Description)</dd>

                        <dt>Shipped On</dt>
                        <dd>@shipment.CreatedAt.ToString("MMMM dd, yyyy")</dd>

                        <dt>Estimated Delivery</dt>
                        <dd>
                            @if (shipment.EstimatedDelivery.HasValue)
                            {
                                <strong class="text-success">@shipment.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")</strong>
                            }
                            else
                            {
                                <span class="text-muted">Not yet determined</span>
                            }
                        </dd>
                    </dl>
                </div>
            </div>

            <!-- Progress visualization -->
            <div class="mt-3">
                <h6>Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @GetProgressPercentage(shipment.Status)%">
                        @GetStatusDisplay(shipment.Status)
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private ShipmentTracker.Client.Models.Shipment? shipment;
    private bool searched;
    private bool isSearching;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isSearching = true;
        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        searched = true;
        isSearching = false;
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await TrackShipment();
        }
    }

    private static string GetStatusDisplay(ShipmentTracker.Client.Models.ShipmentStatus status) => status switch
    {
        ShipmentTracker.Client.Models.ShipmentStatus.PickedUp => "Picked Up",
        ShipmentTracker.Client.Models.ShipmentStatus.InTransit => "In Transit",
        ShipmentTracker.Client.Models.ShipmentStatus.OutForDelivery => "Out for Delivery",
        _ => status.ToString()
    };

    private static int GetProgressPercentage(ShipmentTracker.Client.Models.ShipmentStatus status) => status switch
    {
        ShipmentTracker.Client.Models.ShipmentStatus.Pending => 10,
        ShipmentTracker.Client.Models.ShipmentStatus.PickedUp => 30,
        ShipmentTracker.Client.Models.ShipmentStatus.InTransit => 55,
        ShipmentTracker.Client.Models.ShipmentStatus.OutForDelivery => 80,
        ShipmentTracker.Client.Models.ShipmentStatus.Delivered => 100,
        ShipmentTracker.Client.Models.ShipmentStatus.Delayed => 55,
        _ => 0
    };

    private static string GetStatusBadgeClass(ShipmentTracker.Client.Models.ShipmentStatus status) => status switch
    {
        ShipmentTracker.Client.Models.ShipmentStatus.Pending => "bg-secondary",
        ShipmentTracker.Client.Models.ShipmentStatus.PickedUp => "bg-info",
        ShipmentTracker.Client.Models.ShipmentStatus.InTransit => "bg-primary",
        ShipmentTracker.Client.Models.ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentTracker.Client.Models.ShipmentStatus.Delivered => "bg-success",
        ShipmentTracker.Client.Models.ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentTracker.Client.Models.ShipmentStatus status) => status switch
