using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await db.Shipments.OrderByDescending(s => s.CreatedAt).ToListAsync();
    }

    public async Task<List<Shipment>> GetShipmentsByStatusAsync(ShipmentStatus? status)
    {
        var query = db.Shipments.AsQueryable();
        if (status.HasValue)
        {
            query = query.Where(s => s.Status == status.Value);
        }
        return await query.OrderByDescending(s => s.CreatedAt).ToListAsync();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        return await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.TrackingNumber = $"TRK-{Guid.NewGuid().ToString()[..8].ToUpper()}";
        shipment.CreatedAt = DateTime.UtcNow;
        shipment.Status = ShipmentStatus.Pending;

        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();
        return shipment;
    }

    public async Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = await db.Shipments.FindAsync(id)
            ?? throw new InvalidOperationException($"Shipment {id} not found.");
        shipment.Status = status;
        await db.SaveChangesAsync();
        return shipment;
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments");

        group.MapGet("", async (ShipmentStatus? status, IShipmentService service) =>
        {
            return Results.Ok(await service.GetShipmentsByStatusAsync(status));
        });

        group.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });

        group.MapPost("", async (Shipment shipment, IShipmentService service) =>
        {
            var created = await service.CreateShipmentAsync(shipment);
            return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
        }).RequireAuthorization();

        group.MapPut("{id}/status", async (int id, StatusUpdateRequest request, IShipmentService service) =>
        {
            var updated = await service.UpdateShipmentStatusAsync(id, request.Status);
            return Results.Ok(updated);
        }).RequireAuthorization();
    }
}

public record StatusUpdateRequest(ShipmentStatus Status);

